<script setup lang="ts">import {ref,onMounted} from 'vue';import axios from 'axios';const exams=ref<any[]>([]);const selected=ref('10000000-0000-0000-0000-000000000001');async function load(){exams.value=[{id:selected.value,title:'LabProctor Demo Exam',status:'running'}]}function download(path:string){window.open(`/api/v1/teacher/exams/${selected.value}/exports/${path}`,'_blank')}onMounted(load)</script>
<template><main><h1>Teacher Dashboard</h1><select v-model="selected"><option v-for="e in exams" :value="e.id">{{e.title}} · {{e.status}}</option></select><div class="actions"><button @click="download('sources.zip')">Export source ZIP</button><button @click="download('grades.xlsx')">Export grades</button><button @click="download('screen-logs.xlsx')">Export screen logs</button><RouterLink :to="`/teacher/exams/${selected}/proctor`">Proctor view</RouterLink><RouterLink :to="`/teacher/exams/${selected}/review`">Review papers</RouterLink></div></main></template><style scoped>main{padding:32px;font:16px system-ui}.actions{display:flex;gap:12px;margin-top:24px}button,a{padding:10px;background:#1f4b99;color:#fff;border:0;border-radius:5px;text-decoration:none}</style>
